import re

def parse_range(header, size):
    if not header or 'bytes=' not in header:
        return None

    try:
        # Extract the part after 'bytes='
        range_part = header.split('bytes=')[-1].split(';')[0].strip()
        if not range_part:
            return None

        raw_ranges = range_part.split(',')
        results = []
        any_satisfiable = False

        for r in raw_ranges:
            r = r.strip()
            if not r:
                continue

            parts = r.split('-')
            start_val = None
            end_val = None

            if len(parts) == 1:
                # Case: bytes=-500
                if parts[0].startswith('-'):
                    length = abs(int(parts[0][1:]))
                    start_val = max(0, size - length)
                    end_val = size - 1
                else:
                    # Case: bytes=500 (interpreted as start=500, end=size-1)
                    start_val = int(parts[0])
                    end_val = size - 1
            elif len(parts) == 2:
                # Case: bytes=0-499 or bytes=500-
                p1 = parts[0].strip()
                p2 = parts[1].strip()

                if p1.startswith('-'):
                    length = abs(int(p1[1:]))
                    start_val = max(0, size - length)
                    end_val = size - 1
                else:
                    start_val = int(p1)
                    if not p2:
                        end_val = size - 1
                    else:
                        end_val = int(p2)

                # Clamp end to size
                if end_val >= size:
                    end_val = size - 1
            else:
                continue

            # Validation
            if start_val is not None and start_val < size and start_val <= end_val:
                results.append((start_val, end_val))
                any_satisfiable = True
            elif start_val is not None and start_val >= size:
                # Unsatisfiable range, skip
                pass
            else:
                # Malformed or other unsatisfiable
                pass

        return results if any_satisfiable else None

    except ValueError:
        return None
```

