        self.cells = {}  # cell_id -> value (int or str)
        self.cache = {}  # cell_id -> computed_value
        self.dependencies = {}  # cell_id -> set of cell_ids it depends on
        self.dependents = {}  # cell_id -> set of cell_ids that depend on it

    def _parse_formula(self, formula):
        if not formula.startswith('='):
            return None, []

        expr = formula[1:]
        # Tokenize: numbers, cell refs (A1, B10), and operators (+, -, *)
        tokens = re.findall(r'[A-Z]+\d+|[0-9]+|[\+\-\*]', expr)

        parsed_nodes = []
        for token in tokens:
            if token.isdigit():
                parsed_nodes.append(('num', int(token)))
            elif re.match(r'[A-Z]+\d+', token):
                parsed_nodes.append(('ref', token))
            else:
                parsed_nodes.append(('op', token))
        return parsed_nodes, None

    def _evaluate(self, cell_id):
        val = self.cells.get(cell_id, 0)
        if not isinstance(val, str) or not val.startswith('='):
            return val

        nodes, _ = self._parse_formula(val)

        # Standard Shunting-yard or simple recursive descent for + - *
        # Since we need to handle precedence, we'll use a simple stack-based approach
        def get_val(node):
            if node[0] == 'num': return node[1]
            if node[0] == 'ref': return self.get(node[1])
            return node[1]

        # Basic expression evaluator for + - *
        # First pass: handle *
        stack = []
        i = 0
        while i < len(nodes):
            node = nodes[i]
            if node[0] == 'op' and node[1] == '*':
                left = stack.pop()
                right = nodes[i+1]
                stack.append(left * get_val(right))
                i += 1
            else:
                stack.append(node)
            i += 1

        # Second pass: handle + -
        res = stack[0]
        i = 1
        while i < len(stack):
            node = stack[i]
            if node[0] == 'op':
                if node[1] == '+': res += stack[i+1]
                else: res -= stack[i+1]
            else:
                res = stack[i]
            i += 2
        return res

    def get(self, cell_id):
        if cell_id in self.cache:
            return self.cache[cell_id]

        val = self.cells.get(cell_id, 0)
        if not isinstance(val, str) or not val.startswith('='):
            res = val
        else:
            res = self._evaluate(cell_id)

        self.cache[cell_id] = res
        return res

    def set(self, cell_id, value):
        # Check for cycles
        new_deps = set()
