            nodes, _ = self._parse_formula(value)
            for node in nodes:
                if node[0] == 'ref':
                    new_deps.add(node[1])

        # Cycle detection using DFS
        def has_cycle(start_node, visited, path):
            visited.add(start_node)
            path.add(start_node)
            for neighbor in self.dependencies.get(start_node, []):
                if neighbor not in visited:
                    if has_cycle(neighbor, visited, path): return True
                elif neighbor in path: return True
            path.remove(start_node)
            return False

        # Temporary check
        old_deps = self.dependencies.get(cell_id, set())
        self.dependencies[cell_id] = new_deps

