            self.dependencies[cell_id] = old_deps
            raise ValueError("Cycle detected")

        # Update dependencies and dependents
        if cell_id in self.dependencies:
            for old_dep in old_deps:
                if cell_id in self.dependents.get(old_dep, set()):
                    self.dependents[old_dep].remove(cell_id)

