            const key = keys[i];
            const isLast = i === keys.length - 1;

            if (isLast) {
                if (current[key] === undefined) {
                    current[key] = value;
                } else if (Array.isArray(current[key])) {
                    current[key].push(value);
                } else {
                    current[key] = [current[key], value];
                }
                return;
            }

            const nextKey = keys[i + 1];
            const isNextKeyArray = !isNaN(nextKey);

            if (current[key] === undefined) {
                current[key] = isNextKeyArray ? [] : {};
            }

            if (current[key] !== null && typeof current[key] === 'object') {
                current = current[key];
            } else {
                // Handle case where key exists but is not an object/array
                current[key] = isNextKeyArray ? [] : {};
                current = current[key];
            }
        }
    };

    const pairs = qs.split('&');
    for (const pair of pairs) {
        if (!pair) continue;
        const [rawKey, rawValue] = pair.split('=');
        const keyStr = decode(rawKey);
        const value = rawValue !== undefined ? decode(rawValue) : '';

        const keys = [];
        let currentKey = keyStr;

        // Parse bracket notation: a[b][c] -> ['a', 'b', 'c']
        const parts = keyStr.split(/\[|\]/).filter(Boolean);
        for (let i = 0; i < parts.length; i++) {
            const part = parts[i];
            if (part === '') continue;

            // If it's a numeric string like "0", it's an array index
            if (!isNaN(part) && part !== '') {
                keys.push(Number(part));
            } else {
                keys.push(part);
            }
        }

        // Handle repeated bare keys (e.g., a=1&a=2)
        if (keys.length === 1 && !keyStr.includes('[')) {
            const k = keys[0];
